<script setup>
import {computed,onMounted,ref} from 'vue'
import {ArrowDown,ArrowRight,ArrowUp,Pencil,Plus,Trash2} from '@lucide/vue'
import {api} from '../api'
import {activityLocation,unitLocation} from '../utils/courseActivityNavigation'
const props=defineProps({course:{type:Object,required:true},manage:Boolean}),emit=defineEmits(['changed'])
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),form=ref(null)
const units=computed(()=>data.value?.units||[]),activities=computed(()=>data.value?.activities||[]),unassigned=computed(()=>activities.value.filter(item=>!item.unitId))
const summaries=computed(()=>units.value.map(unit=>{const items=activities.value.filter(item=>item.unitId===unit.id);return {...unit,counts:{material:items.filter(x=>x.kind==='material').length,assessment:items.filter(x=>x.kind!=='material').length},items}}))
async function load(){busy.value=true;error.value='';try{data.value=await api(`/courses/${props.course.id}/curriculum`)}catch(e){error.value=e.message}finally{busy.value=false}}
async function run(action,message){busy.value=true;error.value='';notice.value='';try{await action();notice.value=message;await load();emit('changed');return true}catch(e){error.value=e.message;return false}finally{busy.value=false}}
function add(){form.value={name:'',description:'',expectedVersion:0}}function edit(unit){form.value={id:unit.id,name:unit.name,description:unit.description,expectedVersion:unit.version}}
async function save(){const current=form.value;const saved=await run(()=>api(`/courses/${props.course.id}/units${current.id?'/'+current.id:''}`,{method:current.id?'PUT':'POST',body:current}),current.id?'單元已更新。':'單元已建立。');if(saved)form.value=null}
async function moveOrder(index,direction){const ids=units.value.map(x=>x.id),target=index+direction;[ids[index],ids[target]]=[ids[target],ids[index]];await run(()=>api(`/courses/${props.course.id}/units/reorder`,{method:'PUT',body:{unitIds:ids}}),'單元順序已更新。')}
async function remove(unit){if(!confirm(`刪除「${unit.name}」？只有空單元可以刪除。`))return;await run(()=>api(`/courses/${props.course.id}/units/${unit.id}`,{method:'DELETE'}),'空單元已刪除。')}
async function assign(item,event){await run(()=>api(`/courses/${props.course.id}/units/activities/${item.kind}/${item.id}`,{method:'PUT',body:{unitId:event.target.value}}),'教學活動所屬單元已更新。')}
onMounted(load)
</script>
<template><section class="course-units"><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p>
<div v-if="manage&&data?.canManage" class="section-title"><div><h2>課程內容</h2><p>以單元安排教材、作業與測驗；單元不強制對應週次。</p></div><button class="button primary" :disabled="busy||!!form" @click="add"><Plus :size="16"/>新增單元</button></div>
<form v-if="form" class="surface form-surface" @submit.prevent="save"><fieldset :disabled="busy"><h3>{{form.id?'編輯單元':'新增單元'}}</h3><label>單元名稱<input v-model="form.name" required maxlength="160"/></label><label>單元說明<textarea v-model="form.description" maxlength="8000" rows="4"/></label><button class="button primary">儲存單元</button> <button type="button" class="button secondary" @click="form=null">取消</button></fieldset></form>
<p v-if="busy&&!data" role="status">載入課程內容中…</p><template v-if="data"><article v-for="(unit,index) in summaries" :key="unit.id" class="surface unit-card"><header><div><p class="eyebrow">UNIT {{index+1}}</p><h2>{{unit.name}}</h2><p v-if="unit.description" class="muted">{{unit.description}}</p></div><div v-if="manage&&data.canManage" class="unit-actions"><button class="icon-button" :aria-label="`${unit.name} 上移`" :disabled="busy||index===0" @click="moveOrder(index,-1)"><ArrowUp :size="17"/></button><button class="icon-button" :aria-label="`${unit.name} 下移`" :disabled="busy||index===units.length-1" @click="moveOrder(index,1)"><ArrowDown :size="17"/></button><button class="icon-button" :aria-label="`編輯 ${unit.name}`" :disabled="busy" @click="edit(unit)"><Pencil :size="16"/></button><button class="icon-button unit-delete" :aria-label="`刪除 ${unit.name}`" :disabled="busy||unit.items.length>0" @click="remove(unit)"><Trash2 :size="16"/></button></div></header><div class="unit-summary"><span>{{unit.counts.material}} 份教材</span><span>{{unit.counts.assessment}} 份測驗／作業</span><span>{{unit.items.length}} 項活動</span></div><RouterLink :to="unitLocation(course.id,unit.id)" class="button primary unit-enter">進入單元 <ArrowRight :size="16"/></RouterLink></article>
<article v-if="unassigned.length" class="surface compatibility-card"><header><div><p class="eyebrow">COMPATIBILITY</p><h2>未歸類教學活動</h2><p class="muted">保留舊資料；請將內容移入正式單元。</p></div></header><ol><li v-for="item in unassigned" :key="`${item.kind}:${item.id}`"><RouterLink :to="activityLocation(course.id,item)">{{item.title}}</RouterLink><label v-if="manage&&data.canManage">所屬單元<select :aria-label="`${item.title} 所屬單元`" value="" :disabled="busy" @change="assign(item,$event)"><option disabled value="">未歸類</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{unit.name}}</option></select></label></li></ol></article><p v-if="!units.length" class="surface empty-inline">尚未建立課程單元。{{data.canManage?'請新增第一個單元，再安排教材與評量。':''}}</p></template></section></template>
<style scoped>.course-units{display:grid;gap:18px}.unit-card,.compatibility-card{padding:22px}.unit-card>header,.compatibility-card>header{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.unit-card h2{font-size:19px}.unit-card .muted{white-space:pre-wrap;margin-top:5px}.unit-actions{display:flex;gap:3px}.unit-delete{color:var(--danger)}.unit-summary{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0;color:var(--muted);font-size:.86rem}.unit-summary span{padding:6px 9px;background:var(--surface-muted);border-radius:999px}.unit-enter{width:max-content}.compatibility-card{border-style:dashed}.compatibility-card ol{list-style:none;padding:0;margin:12px 0 0}.compatibility-card li{display:grid;grid-template-columns:minmax(0,1fr) minmax(180px,260px);align-items:center;gap:14px;padding:10px 0;border-top:1px solid var(--line)}@media(max-width:650px){.unit-card>header{flex-direction:column}.unit-actions{align-self:flex-end}.compatibility-card li{grid-template-columns:1fr}}</style>
